# Let me try identification of runs in EXACT terms

def find_runs(grid):
    """Find all horizontal runs of non-5s and their output patterns"""
    runs = []
    for r in range(len(grid)):
        c = 0
        while c < len(grid[0]):
            if grid[r][c] != 5:
                run_start = c
                run_end = c
                while run_end < len(grid[0]) and grid[r][run_end] != 5:
                    run_end += 1
                run_length = run_end - run_start

                # Get output pattern for THIS run in THIS row
                output_start = grid[r][c] if grid[r][c] != 5 else 5
                output_end = c + run_length

                patterns = []
                for i in range(run_start, run_end):
                    patterns.append((i, grid[r][i] if grid[r][i] != 5 else 5, demo2_output[r][i]))

                runs.append({
                    'row': r, 'start': run_start, 'end': run_end, 'length': run_length,
                    'output_patterns': patterns
                })
                c = run_end
            else:
                c += 1
    return runs

